<script setup>
import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MTag from '../../../components/mds/MTag.vue';
defineProps({ rows: { type: Array, default: () => [] }, unread: { type: Number, default: 0 }, canAck: Boolean, working: Boolean, error: { type: String, default: '' }, safeAreaStyle: { type: Object, default: () => ({}) } }); const emit = defineEmits(['back', 'read', 'read-all']);
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Thông báo nhắc" @back="emit('back')"><template #actions><MButton v-if="canAck && unread" variant="link" class="[&]:h-[var(--mds-mobile-touch-target)]" :loading="working" @click="emit('read-all')">Đọc hết</MButton></template></MMobileTopBar><p v-if="error" class="mds-mobile-gutter-x mx-0 py-2 text-[13px] text-[var(--mds-danger)]">{{ error }}</p><div class="min-h-0 flex-1 overflow-y-auto"><div v-if="rows.length" class="divide-y divide-[var(--mds-border-light)]"><article v-for="row in rows" :key="row.id" class="mds-mobile-gutter-x py-3" :class="row.read ? '' : 'bg-[var(--mds-brand-50)]'"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><strong class="block text-[14px] leading-5">{{ row.title }}</strong><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ row.occurDate }}<span v-if="row.subjectName"> · {{ row.subjectName }}</span></p></div><MTag :color="row.read ? 'neutral' : 'brand'">{{ row.read ? 'Đã đọc' : 'Mới' }}</MTag></div><p v-if="row.note" class="mt-2 text-[13px] leading-[18px]">{{ row.note }}</p><MButton v-if="canAck && !row.read" variant="link" class="mt-1 [&]:h-[var(--mds-mobile-touch-target)]" :disabled="working" @click="emit('read', row)">Đánh dấu đã đọc</MButton></article></div><MEmptyState v-else title="Chưa có thông báo nhắc" description="Thông báo mới sẽ xuất hiện khi đến lịch nhắc." /></div></section></template>
